def write_batch(batch, name):
    for p in batch:
        assert 0.0 <= p["confidence"] <= 1.0, p["case_id"]
        for k in ("case_id","prediction_text","basis","confidence","trigger"):
            assert k in p, (p["case_id"], k)
        for bk in ("changed_main","reserve_used","disputed","reason"):
            assert bk in p["trigger"], (p["case_id"], bk)
        path = os.path.join(PRED_DIR, p["case_id"] + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(p, f, ensure_ascii=False, indent=1)
    print(name, "written", len(batch))

write_batch(B23, "B23")
write_batch(B24, "B24")
print("TOTAL", len(B23) + len(B24))
